html:
{#- ================================================================
    NLSIU — Applicant Application Form — Print Format  v5-final
    • No colon column — 5-col grid: lbl | val | lbl | val | photo
    • col widths: 22% | 27% | 22% | auto | 27mm
    • All colspans corrected for 5-col (no colon) grid
    • @page A4, margin 8mm → content 194mm × 281mm
    • 7pt compact font, plain white label cells (no yellow/bold)
    • print-color-adjust: exact on all colored elements
    • tr { page-break-inside: avoid }
    ================================================================ -#}

{%- set _site = frappe.utils.get_url() -%}

{%- macro f(v) -%}{%- if v and v != 'None' -%}{{ v }}{%- else -%}&mdash;{%- endif -%}{%- endmacro -%}
{%- macro fd(v) -%}{%- if v -%}{{ frappe.utils.formatdate(v,'dd-MM-yyyy') }}{%- else -%}&mdash;{%- endif -%}{%- endmacro -%}

{%- set is_phd        = (doc.program_level or '') | lower in ['phd', 'research course'] -%}
{%- set show_guardian = doc.guardian_required -%}
{%- set _ews_val      = (doc.ews or '') | lower -%}
{%- set _pwd_val      = (doc.pwd or '') | lower -%}

<style>
/* ── A4 setup ─────────────────────────────────────────────── */
@page { size: A4 portrait; margin: 8mm; }

/* ── Reset ─────────────────────────────────────────────────── */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

/* ── Base ────────────────────────────────────────────────────── */
html, body {
  width: 184mm; max-width: 184mm;
  font-family: Arial, Helvetica, sans-serif;
  font-size: 7pt; color: #111; background: #fff;
  -webkit-print-color-adjust: exact;
  print-color-adjust: exact;
}

/* ── Page wrapper ─────────────────────────────────────────────── */
.pf-page {
  width: 194mm; max-width: 194mm; min-height: 281mm;
  margin: 0 auto; background: #fff;
  border: 1.5px solid #7b1a1a;
  page-break-after: always; overflow: hidden;
}
.pf-page:last-child { page-break-after: auto; }

@media print {
  html, body { width: 194mm; max-width: 194mm; }
  .pf-page {
    width: 194mm; max-width: 194mm;
    border: 1.5px solid #7b1a1a;
    page-break-after: always; margin: 0; overflow: hidden;
  }
  .pf-page:last-child { page-break-after: auto; }
  .no-print { display: none !important; }
  tr { page-break-inside: avoid; }
}
@media screen {
  body { padding: 8px; background: #c8c8c8; }
  .pf-page { box-shadow: 0 2px 14px rgba(0,0,0,.25); margin: 12px auto; }
}

/* ── Header ───────────────────────────────────────────────────── */
.pf-header {
  background: #7b1a1a; color: #fff;
  display: flex; align-items: center;
  padding: 6px 10px; gap: 10px;
  -webkit-print-color-adjust: exact; print-color-adjust: exact;
}
.pf-logo {
  width: 40px; height: 40px; flex-shrink: 0;
  background: #fff; border-radius: 2px;
  display: flex; align-items: center; justify-content: center; overflow: hidden;
}
.pf-logo img { width: 36px; height: 36px; object-fit: contain; }
.pf-logo-text { font-size: 6pt; color: #7b1a1a; font-weight: bold; text-align: center; line-height: 1.2; }
.pf-hdr-body { flex: 1; text-align: center; }
.pf-hdr-inst { font-size: 11pt; font-weight: bold; text-transform: uppercase; letter-spacing: .5px; line-height: 1.2; color: #fff; }
.pf-hdr-sub  { font-size: 6.5pt; letter-spacing: 1.2px; text-transform: uppercase; margin-top: 2px; color: #ffdddd; }

/* ── Title bar ────────────────────────────────────────────────── */
.pf-title-bar { text-align: center; padding: 4px 8px 3px; background: #fff; border-bottom: 1px solid #ccc; }
.pf-title    { font-size: 9pt; font-weight: bold; color: #111; }
.pf-subtitle { font-size: 7pt; color: #555; margin-top: 1px; }
.sep         { margin: 0 4px; color: #bbb; }

/* ── Main table ────────────────────────────────────────────────── */
/*
   5-COLUMN GRID (no colon column):
     col1: label  22%
     col2: value  27%
     col3: label  22%
     col4: value  auto (fills remaining)
     col5: photo  27mm (fixed)

   colspan reference:
     full-width (no photo):  colspan="4"
     full-width (with photo span): colspan="4" within the rowspan zone
     paired row value only:  td col4 = natural auto
     section headers:        colspan="5"
*/
.pf-table {
  width: 100%;
  border-collapse: collapse;
  table-layout: fixed;
}
/* Define col widths via colgroup in HTML */
.pf-table td {
  border: 1px solid #ccc;
  padding: 2px 6px;
  vertical-align: middle;
  font-size: 7pt;
  line-height: 1.35;
  word-wrap: break-word;
  overflow-wrap: break-word;
}

/* Section bar */
.pf-sec {
  background: #7b1a1a !important; color: #fff !important;
  font-weight: bold; font-size: 7.5pt;
  letter-spacing: .3px; text-transform: uppercase;
  padding: 3px 8px; border: none !important;
  -webkit-print-color-adjust: exact; print-color-adjust: exact;
}
/* Sub-section bar */
.pf-subsec {
  background: #f5e6e6 !important; color: #7b1a1a !important;
  font-weight: bold; font-size: 7pt;
  padding: 2px 8px; border-color: #ccc !important;
  -webkit-print-color-adjust: exact; print-color-adjust: exact;
}

/* Label — plain white, normal weight */
.pf-lbl { font-weight: normal; color: #222; background: #fff; white-space: normal; word-wrap: break-word; }
/* Value */
.pf-val { color: #111; background: #fff; }

/* Photo cell */
.pf-photo {
  width: 27mm !important; text-align: center;
  vertical-align: middle; border: 1px solid #ccc !important;
  padding: 3px; background: #fff;
}
.pf-photo img {
  width: 25mm; height: 33mm;
  object-fit: cover; display: block; margin: 0 auto; border: 1px solid #ddd;
}
.pf-photo-cap { font-size: 6pt; color: #666; margin-top: 3px; text-align: center; }
.pf-photo-empty {
  width: 25mm; height: 33mm; background: #f8f8f8;
  border: 1px dashed #bbb; display: flex; align-items: center;
  justify-content: center; font-size: 6pt; color: #aaa; text-align: center; margin: 0 auto;
}

/* Badges */
.badge-green  { background:#2e7d32; color:#fff; font-weight:bold; padding:1px 7px; border-radius:2px; font-size:7pt; display:inline-block; -webkit-print-color-adjust:exact; print-color-adjust:exact; }
.badge-yellow { background:#b45309; color:#fff; font-weight:bold; padding:1px 7px; border-radius:2px; font-size:7pt; display:inline-block; -webkit-print-color-adjust:exact; print-color-adjust:exact; }
.badge-red    { background:#b91c1c; color:#fff; font-weight:bold; padding:1px 7px; border-radius:2px; font-size:7pt; display:inline-block; -webkit-print-color-adjust:exact; print-color-adjust:exact; }
.badge-grey   { background:#555;    color:#fff; font-weight:bold; padding:1px 7px; border-radius:2px; font-size:7pt; display:inline-block; -webkit-print-color-adjust:exact; print-color-adjust:exact; }

/* Child degree table */
.deg-table { width:100%; border-collapse:collapse; font-size:7pt; }
.deg-table th { background:#f5e6e6 !important; color:#7b1a1a; font-weight:bold; padding:2px 6px; border:1px solid #ccc; text-align:left; font-size:6.5pt; -webkit-print-color-adjust:exact; print-color-adjust:exact; }
.deg-table td { padding:2px 6px; border:1px solid #ccc; vertical-align:middle; font-size:7pt; }
.deg-table tr:nth-child(even) td { background:#fafafa; }

/* Declaration */
.pf-decl { padding:5px 10px 4px; font-size:7pt; line-height:1.5; color:#111; background:#fff; border-top:1px solid #ccc; }
.pf-decl-item { display:flex; align-items:flex-start; gap:6px; margin-bottom:3px; }
.pf-decl-item:last-child { margin-bottom:0; }
.pf-chk { font-size:10pt; line-height:1; flex-shrink:0; }
.pf-decl-text { flex:1; }

/* Invigilator */
.pf-invig { text-align:center; font-size:7pt; font-style:italic; color:#555; padding:3px 10px; background:#fafafa; border-top:1px solid #ccc; }

/* Signature */
.pf-sig-table { width:100%; border-collapse:collapse; border-top:1px solid #ccc; }
.pf-sig-table td { border:1px solid #ccc; padding:3px 12px 10px; text-align:center; font-size:7pt; vertical-align:bottom; width:50%; }
.pf-sig-head  { font-weight:bold; background:#fafafa; }
.pf-sig-space { height:26px; display:block; }

/* Footer */
.pf-footer { border-top:1px dashed #ccc; text-align:center; font-size:6.5pt; color:#777; padding:3px 8px; background:#fff; }

/* Doc pages */
.pf-doc-page {
  width:194mm; max-width:194mm; min-height:281mm;
  margin:0 auto; background:#fff;
  border:1.5px solid #7b1a1a;
  page-break-after:always; overflow:hidden;
}
.pf-doc-page:last-child { page-break-after:auto; }
@media screen { .pf-doc-page { box-shadow:0 2px 14px rgba(0,0,0,.25); margin:12px auto; } }
.pf-doc-body { padding:6mm 8mm; }
.pf-doc-label { font-weight:bold; font-size:7.5pt; color:#fff; background:#7b1a1a; padding:3px 8px; margin-bottom:3px; -webkit-print-color-adjust:exact; print-color-adjust:exact; }
.pf-doc-image { text-align:center; border:1px solid #ccc; padding:4px; }
.pf-doc-image img { max-width:100%; max-height:170mm; }
.pf-doc-pdf { padding:10px; background:#fafafa; border:1px solid #ccc; text-align:center; color:#555; font-size:7.5pt; }
</style>



<div class="pf-page">

  <div class="pf-header">
    <div class="pf-logo">
      {%- set _logo = frappe.db.get_single_value('Institution Settings','logo') -%}
      {%- if _logo -%}<img src="{{ _site }}{{ _logo }}" alt="Logo">
      {%- else -%}<span class="pf-logo-text">NLSIU</span>{%- endif -%}
    </div>
    <div class="pf-hdr-body">
      <div class="pf-hdr-inst">National Law School of India University</div>
      <div class="pf-hdr-sub">Bengaluru &nbsp;·&nbsp; Office of Admissions &nbsp;·&nbsp; Examination Cell</div>
    </div>
  </div>

  <div class="pf-title-bar">
    <div class="pf-title">Application Form{%- if doc.program %} &mdash; {{ doc.program }}{%- endif -%}</div>
    <div class="pf-subtitle">
      Admission to {{ doc.program or '' }}
      {%- if doc.academic_year -%}<span class="sep">|</span>{{ doc.academic_year }}{%- endif -%}
      {%- if doc.name -%}<span class="sep">|</span>{{ doc.name }}{%- endif -%}
    </div>
  </div>


  <table class="pf-table">
    <colgroup>
      <col style="width:22%">
      <col style="width:28%">
      <col style="width:22%">
      <col><!-- auto — absorbs remaining after photo -->
      <col style="width:27mm">
    </colgroup>


    <tr><td colspan="5" class="pf-sec">1. Personal Information</td></tr>


    <tr>
      <td class="pf-lbl">Application ID</td>
      <td class="pf-val">{{ doc.name }}</td>
      <td class="pf-lbl">Status</td>
      {%- set _st = doc.application_status or 'Draft' -%}
      <td class="pf-val">
        {%- if _st in ['Approved','Admitted','Allocated','Verified'] -%}<span class="badge-green">{{ _st }}</span>
        {%- elif _st in ['Pending','Under Review','Submitted'] -%}<span class="badge-yellow">{{ _st }}</span>
        {%- elif _st in ['Rejected','Cancelled'] -%}<span class="badge-red">{{ _st }}</span>
        {%- else -%}<span class="badge-grey">{{ _st }}</span>{%- endif -%}
      </td>
      <td class="pf-photo" rowspan="9">
        {%- if doc.candidate_photo -%}
          <img src="{{ _site }}{{ doc.candidate_photo }}" alt="Photo">
        {%- else -%}
          <div class="pf-photo-empty">Photo<br>Not<br>Uploaded</div>
        {%- endif -%}
        <div class="pf-photo-cap">Candidate's<br>Photograph</div>
      </td>
    </tr>

    <tr>
      <td class="pf-lbl">Candidate's Name</td>
      <td class="pf-val" colspan="3">
        {%- if doc.title and doc.title not in ['None',''] -%}{{ doc.title }}&nbsp;{%- endif -%}{{ f(doc.candidate_name) }}
      </td>
    </tr>
    <tr>
      <td class="pf-lbl">Date of Birth</td>
      <td class="pf-val" colspan="3">{{ fd(doc.date_of_birth) }}</td>
    </tr>
    <tr>
      <td class="pf-lbl">Gender</td>
      <td class="pf-val" colspan="3">{{ f(doc.gender) }}</td>
    </tr>
    <tr>
      <td class="pf-lbl">Nationality</td>
      <td class="pf-val">{{ f(doc.nationality) }}</td>
      <td class="pf-lbl">Religion</td>
      <td class="pf-val">{{ f(doc.religion) }}</td>
    </tr>
    <tr>
      <td class="pf-lbl">Mobile Number</td>
      <td class="pf-val">{{ f(doc.mobile_number) }}</td>
      <td class="pf-lbl">Alternate Contact</td>
      <td class="pf-val">{{ f(doc.alternate_contact) }}</td>
    </tr>
    <tr>
      <td class="pf-lbl">Email Address</td>
      <td class="pf-val" colspan="3">{{ f(doc.email) }}</td>
    </tr>
    <tr>
      <td class="pf-lbl">Programme Applied</td>
      <td class="pf-val">{{ f(doc.program) }}</td>
      <td class="pf-lbl">Academic Year</td>
      <td class="pf-val">{{ f(doc.academic_year) }}</td>
    </tr>
    <tr>
      <td class="pf-lbl">Annual Household Income</td>
      <td class="pf-val" colspan="3">{{ f(doc.annual_house_hold_income) }}</td>
    </tr>


    <tr>
      <td class="pf-lbl">Correspondence Address</td>
      <td class="pf-val" colspan="4">
        {{ f(doc.correspondence_address) }}
        {%- if doc.city -%}, {{ doc.city }}{%- endif -%}
        {%- if doc.state -%}, {{ doc.state }}{%- endif -%}
        {%- if doc.pincode %} &ndash; {{ doc.pincode }}{%- endif -%}
      </td>
    </tr>


    <tr><td colspan="5" class="pf-sec">2. Family Information</td></tr>

    {%- if show_guardian -%}
    <tr>
      <td class="pf-lbl">Guardian's Name</td>
      <td class="pf-val">{{ f(doc.guardian_name) }}</td>
      <td class="pf-lbl">Guardian's Mobile</td>
      <td class="pf-val" colspan="2">{{ f(doc.guardian_mobile) }}</td>
    </tr>
    <tr>
      <td class="pf-lbl">Guardian's Email</td>
      <td class="pf-val" colspan="4">{{ f(doc.guardian_email) }}</td>
    </tr>
    {%- else -%}
    <tr>
      <td class="pf-lbl">Father's Name</td>
      <td class="pf-val">{{ f(doc.father_name) }}</td>
      <td class="pf-lbl">Father's Occupation</td>
      <td class="pf-val" colspan="2">{{ f(doc.father_occupation) }}</td>
    </tr>
    <tr>
      <td class="pf-lbl">Father's Mobile</td>
      <td class="pf-val">{{ f(doc.father_mobile) }}</td>
      <td class="pf-lbl">Father's Email</td>
      <td class="pf-val" colspan="2">{{ f(doc.father_email) }}</td>
    </tr>
    <tr>
      <td class="pf-lbl">Mother's Name</td>
      <td class="pf-val">{{ f(doc.mother_name) }}</td>
      <td class="pf-lbl">Mother's Occupation</td>
      <td class="pf-val" colspan="2">{{ f(doc.mother_occupation) }}</td>
    </tr>
    <tr>
      <td class="pf-lbl">Mother's Mobile</td>
      <td class="pf-val">{{ f(doc.mother_mobile) }}</td>
      <td class="pf-lbl">Mother's Email</td>
      <td class="pf-val" colspan="2">{{ f(doc.mother_email) }}</td>
    </tr>
    {%- endif -%}


    <tr><td colspan="5" class="pf-sec">3. Academic Details</td></tr>

    <tr><td colspan="5" class="pf-subsec">Class X &mdash; Secondary School</td></tr>
    <tr>
      <td class="pf-lbl">School Name</td>
      <td class="pf-val" colspan="4">{{ f(doc.class_x_school) }}</td>
    </tr>
    <tr>
      <td class="pf-lbl">Board</td>
      <td class="pf-val">{{ f(doc.class_x_board) }}</td>
      <td class="pf-lbl">Year of Completion</td>
      <td class="pf-val" colspan="2">{{ f(doc.class_x_year_of_completion) }}</td>
    </tr>
    <tr>
      <td class="pf-lbl">Percentage (%)</td>
      <td class="pf-val">{{ f(doc.class_x_percentage) }}</td>
      <td class="pf-lbl">CGPA</td>
      <td class="pf-val" colspan="2">{{ f(doc.class_x_cgpa) }}</td>
    </tr>

    <tr><td colspan="5" class="pf-subsec">Class XII &mdash; Higher Secondary</td></tr>
    <tr>
      <td class="pf-lbl">Examination Name</td>
      <td class="pf-val" colspan="4">{{ f(doc.class_xii_name_of_examination) }}</td>
    </tr>
    <tr>
      <td class="pf-lbl">School / College</td>
      <td class="pf-val" colspan="4">{{ f(doc.class_xii_school) }}</td>
    </tr>
    <tr>
      <td class="pf-lbl">Board</td>
      <td class="pf-val">{{ f(doc.class_xii_board) }}</td>
      <td class="pf-lbl">Year of Completion</td>
      <td class="pf-val" colspan="2">{{ f(doc.class_xii_year_of_completion) }}</td>
    </tr>
    <tr>
      <td class="pf-lbl">Percentage (%)</td>
      <td class="pf-val">{{ f(doc.class_xii_percentage) }}</td>
      <td class="pf-lbl">CGPA</td>
      <td class="pf-val" colspan="2">{{ f(doc.class_xii_cgpa) }}</td>
    </tr>
    {%- if doc.hsc_group or doc.hsc_percentage -%}
    <tr>
      <td class="pf-lbl">HSC Group / Stream</td>
      <td class="pf-val">{{ f(doc.hsc_group) }}</td>
      <td class="pf-lbl">HSC Percentage</td>
      <td class="pf-val" colspan="2">{{ f(doc.hsc_percentage) }}</td>
    </tr>
    {%- endif -%}

    {%- if doc.national_test_name or doc.percentage -%}
    <tr><td colspan="5" class="pf-subsec">National / Entrance Test</td></tr>
    <tr>
      <td class="pf-lbl">Test Name</td>
      <td class="pf-val">{{ f(doc.national_test_name) }}</td>
      <td class="pf-lbl">Score / Percentile</td>
      <td class="pf-val" colspan="2">{{ f(doc.percentage) }}</td>
    </tr>
    {%- endif -%}


    {%- if not is_phd and doc.ug_degree_details -%}
    <tr><td colspan="5" class="pf-subsec">Undergraduate Degree(s)</td></tr>
    <tr>
      <td colspan="5" style="padding:4px 8px;">
        <table class="deg-table">
          <tr><th style="width:30%">Programme</th><th style="width:40%">College / University</th><th style="width:15">Year</th><th style="width:15%">% / CGPA</th></tr>
          {%- for d in doc.ug_degree_details -%}
          <tr><td>{{ f(d.ug_program) }}</td><td>{{ f(d.college) }}</td><td>{{ f(d.year_of_completion) }}</td><td>{{ f(d.ug_cgpa or d.percentage_cgpa_obtained) }}</td></tr>
          {%- else -%}
          <tr><td colspan="4" style="color:#999;text-align:center;">&mdash;</td></tr>
          {%- endfor -%}
        </table>
      </td>
    </tr>
    {%- if doc.ug_degree_completion -%}
    <tr>
      <td class="pf-lbl">UG Completion Status</td>
      <td class="pf-val" colspan="4">{{ f(doc.ug_degree_completion) }}</td>
    </tr>
    {%- endif -%}
    {%- endif -%}


    {%- if is_phd -%}
    <tr><td colspan="5" class="pf-subsec">Undergraduate Degree(s)</td></tr>
    <tr>
      <td colspan="5" style="padding:4px 8px;">
        <table class="deg-table">
          <tr><th style="width:30%">Programme</th><th style="width:40%">College / University</th><th style="width:15%">Year</th><th style="width:15%">% / CGPA</th></tr>
          {%- for d in (doc.ug_degree_details or []) -%}
          <tr><td>{{ f(d.ug_program) }}</td><td>{{ f(d.college) }}</td><td>{{ f(d.year_of_completion) }}</td><td>{{ f(d.ug_cgpa or d.percentage_cgpa_obtained) }}</td></tr>
          {%- else -%}<tr><td colspan="4" style="color:#999;text-align:center;">&mdash;</td></tr>{%- endfor -%}
        </table>
      </td>
    </tr>
    <tr><td colspan="5" class="pf-subsec">Postgraduate Degree(s)</td></tr>
    <tr>
      <td colspan="5" style="padding:4px 8px;">
        <table class="deg-table">
          <tr><th style="width:30%">Programme</th><th style="width:40%">College / University</th><th style="width:15%">Year</th><th style="width:15%">% / CGPA</th></tr>
          {%- for d in (doc.pg_degree_details or []) -%}
          <tr><td>{{ f(d.pg_program) }}</td><td>{{ f(d.collegeuniversity) }}</td><td>{{ f(d.year_of_completion) }}</td><td>{{ f(d.pg_cgpa or d.percentagecgpa_obtained) }}</td></tr>
          {%- else -%}<tr><td colspan="4" style="color:#999;text-align:center;">&mdash;</td></tr>{%- endfor -%}
        </table>
      </td>
    </tr>
    {%- if doc.phd_program_type or doc.proposed_phd_topic -%}
    <tr><td colspan="5" class="pf-subsec">PhD Programme Details</td></tr>
    {%- if doc.phd_program_type -%}
    <tr><td class="pf-lbl">PhD Programme Type</td><td class="pf-val" colspan="4">{{ f(doc.phd_program_type) }}</td></tr>
    {%- endif -%}
    {%- if doc.proposed_phd_topic -%}
    <tr><td class="pf-lbl">Proposed PhD Topic</td><td class="pf-val" colspan="4">{{ f(doc.proposed_phd_topic) }}</td></tr>
    {%- endif -%}
    {%- endif -%}
    {%- endif -%}

    {%- if doc.post_degree_work_experience or doc.years_of_work_experience -%}
    <tr><td colspan="5" class="pf-subsec">Work Experience</td></tr>
    <tr>
      <td class="pf-lbl">Work Experience</td>
      <td class="pf-val">{{ f(doc.post_degree_work_experience) }}</td>
      <td class="pf-lbl">Years of Experience</td>
      <td class="pf-val" colspan="2">{{ f(doc.years_of_work_experience) }}</td>
    </tr>
    {%- endif -%}


    <tr><td colspan="5" class="pf-sec">4. Reservation / Category Details</td></tr>
    <tr>
      <td class="pf-lbl">Reservation Category</td>
      <td class="pf-val" colspan="4">{{ f(doc.karnataka_category) }}</td>
    </tr>
    {%- if _ews_val and _ews_val not in ['no','none',''] -%}
    <tr>
      <td class="pf-lbl">EWS Status</td>
      <td class="pf-val">{{ f(doc.ews) }}</td>
      <td class="pf-lbl">EWS Certificate</td>
      <td class="pf-val" colspan="2">{% if doc.ews_certificate %}Uploaded{% else %}&mdash;{% endif %}</td>
    </tr>
    {%- endif -%}
    {%- if doc.caste_certificate -%}
    <tr><td class="pf-lbl">Caste Certificate</td><td class="pf-val" colspan="4">Uploaded</td></tr>
    {%- endif -%}
    {%- if _pwd_val and _pwd_val not in ['no','none',''] -%}
    <tr><td colspan="5" class="pf-subsec">Persons with Disability (PwD)</td></tr>
    <tr>
      <td class="pf-lbl">PwD Status</td>
      <td class="pf-val">{{ f(doc.pwd) }}</td>
      <td class="pf-lbl">PwD Certificate</td>
      <td class="pf-val" colspan="2">{% if doc.pwd_certificate %}Uploaded{% else %}&mdash;{% endif %}</td>
