    <tr>
      <td class="pf-lbl">Requires Special Test</td>
      <td class="pf-val">{{ f(doc.pwd_required_test) }}</td>
      <td class="pf-lbl">Scribe Allotment</td>
      <td class="pf-val" colspan="2">{{ f(doc.scribe_allotment) }}</td>
    </tr>
    {%- endif -%}
    {%- if doc.karnataka_category and doc.karnataka_category not in ['None',''] -%}
    <tr><td colspan="5" class="pf-subsec">Karnataka Category</td></tr>
    {%- if doc.ka_study_7yrs -%}
    <tr><td class="pf-lbl">Studied in Karnataka (7 yrs)</td><td class="pf-val">Yes</td><td class="pf-lbl">Certificate</td><td class="pf-val" colspan="2">{% if doc.ka_study_7yrs_certificate %}Uploaded{% else %}&mdash;{% endif %}</td></tr>
    {%- endif -%}
    {%- if doc.ka_defence_child -%}
    <tr><td class="pf-lbl">Child of Defence Personnel</td><td class="pf-val">Yes</td><td class="pf-lbl">Certificate</td><td class="pf-val" colspan="2">{% if doc.ka_defence_child_certificate %}Uploaded{% else %}&mdash;{% endif %}</td></tr>
    {%- endif -%}
    {%- if doc.ka_govt_child -%}
    <tr><td class="pf-lbl">Child of Karnataka Govt. Employee</td><td class="pf-val">Yes</td><td class="pf-lbl">Certificate</td><td class="pf-val" colspan="2">{% if doc.ka_govt_child_certificate %}Uploaded{% else %}&mdash;{% endif %}</td></tr>
    {%- endif -%}
    {%- if doc.ka_ais_child -%}
    <tr><td class="pf-lbl">Child of AIS Officer</td><td class="pf-val">Yes</td><td class="pf-lbl">Certificate</td><td class="pf-val" colspan="2">{% if doc.ka_ais_child_certificate %}Uploaded{% else %}&mdash;{% endif %}</td></tr>
    {%- endif -%}
    {%- if doc.ka_capf_child -%}
    <tr><td class="pf-lbl">Child of CAPF Personnel</td><td class="pf-val">Yes</td><td class="pf-lbl">Certificate</td><td class="pf-val" colspan="2">{% if doc.ka_capf_child_certificate %}Uploaded{% else %}&mdash;{% endif %}</td></tr>
    {%- endif -%}
    {%- endif -%}


    <tr><td colspan="5" class="pf-sec">5. Other Information</td></tr>
    <tr>
      <td class="pf-lbl">Source of Information</td>
      <td class="pf-val">{{ f(doc.source_of_information) }}</td>
      {%- if doc.please_mention -%}
      <td class="pf-lbl">Please Mention</td>
      <td class="pf-val" colspan="2">{{ f(doc.please_mention) }}</td>
      {%- else -%}
      <td colspan="3"></td>
      {%- endif -%}
    </tr>
    {%- if doc.cv -%}
    <tr><td class="pf-lbl">CV / Resume</td><td class="pf-val" colspan="4">Uploaded</td></tr>
    {%- endif -%}

  </table>

  <div class="pf-decl">
