</div>





{%- set _docs = [] -%}
{%- set _flds = [
  ('ID Proof',                    doc.id_proof),
  ('Class X Marksheet',           doc.class_x_marksheet),
  ('Class XII Marksheet',         doc.class_xii_marksheet),
  ('EWS Certificate',             doc.ews_certificate),
  ('Caste Certificate',           doc.caste_certificate),
  ('PwD Certificate',             doc.pwd_certificate),
  ('Karnataka Study Certificate', doc.ka_study_7yrs_certificate),
  ('Defence Child Certificate',   doc.ka_defence_child_certificate),
  ('Govt. Employee Certificate',  doc.ka_govt_child_certificate),
  ('AIS Officer Certificate',     doc.ka_ais_child_certificate),
  ('CAPF Certificate',            doc.ka_capf_child_certificate),
  ('CV / Resume',                 doc.cv),
  ('PhD Research Proposal',       doc.phd_proposal),
] -%}
{%- for lbl, furl in _flds -%}
  {%- if furl and furl not in ['None',''] -%}{%- set _ = _docs.append({'label': lbl, 'url': furl}) -%}{%- endif -%}
{%- endfor -%}
{%- for d in (doc.ug_degree_details or []) -%}
  {%- if d.degree_certificate -%}{%- set _ = _docs.append({'label': 'UG Degree Certificate (' ~ (d.ug_program or '') ~ ')', 'url': d.degree_certificate}) -%}{%- endif -%}
  {%- if d.marksheets -%}{%- set _ = _docs.append({'label': 'UG Marksheets (' ~ (d.ug_program or '') ~ ')', 'url': d.marksheets}) -%}{%- endif -%}
{%- endfor -%}
{%- for d in (doc.pg_degree_details or []) -%}
  {%- if d.pg_degree_certificatebonafide_certificate_to_be_uploaded -%}{%- set _ = _docs.append({'label': 'PG Degree Certificate (' ~ (d.pg_program or '') ~ ')', 'url': d.pg_degree_certificatebonafide_certificate_to_be_uploaded}) -%}{%- endif -%}
  {%- if d.transcriptsmarksheets_to_be_uploaded -%}{%- set _ = _docs.append({'label': 'PG Transcripts (' ~ (d.pg_program or '') ~ ')', 'url': d.transcriptsmarksheets_to_be_uploaded}) -%}{%- endif -%}
{%- endfor -%}
{%- if doc.get('documents') -%}
  {%- for d in doc.documents -%}
    {%- if d.file -%}{%- set _ = _docs.append({'label': d.document_type or 'Document', 'url': d.file}) -%}{%- endif -%}
  {%- endfor -%}
{%- endif -%}

{%- if _docs -%}
<div class="pf-doc-page">

  <div class="pf-header">
    <div class="pf-logo">
      {%- set _logo = frappe.db.get_single_value('Institution Settings','logo') -%}
      {%- if _logo -%}<img src="{{ _site }}{{ _logo }}" alt="Logo">
      {%- else -%}<span class="pf-logo-text">NLSIU</span>{%- endif -%}
    </div>
    <div class="pf-hdr-body">
      <div class="pf-hdr-inst">National Law School of India University</div>
      <div class="pf-hdr-sub">Uploaded Documents &nbsp;·&nbsp; {{ doc.candidate_name }} &nbsp;·&nbsp; {{ doc.name }}</div>
    </div>
  </div>

  <div class="pf-title-bar">
    <div class="pf-title">Supporting Documents</div>
    <div class="pf-subtitle">
      {{ doc.program or '' }}{%- if doc.academic_year %}<span class="sep">|</span>{{ doc.academic_year }}{%- endif -%}
    </div>
  </div>

  <div class="pf-doc-body">
    {%- for item in _docs -%}
      {%- set _ext = (item.url or '').split('.')[-1] | lower -%}
      {%- set _is_img = _ext in ['jpg','jpeg','png','gif','webp','bmp'] -%}
      <div style="margin-bottom:12px; page-break-inside:avoid;">
        <div class="pf-doc-label">{{ loop.index }}. {{ item.label }}</div>
        {%- if _is_img -%}
        <div class="pf-doc-image"><img src="{{ _site }}{{ item.url }}" alt="{{ item.label }}"></div>
        {%- else -%}
        <div class="pf-doc-pdf">
          <strong>{{ item.label }}</strong><br>
          <span style="font-size:7pt;">{{ item.url.split('/')[-1] }}</span><br>
          <span style="font-size:6.5pt;color:#999;">(Open the portal to view this document)</span>
        </div>
        {%- endif -%}
      </div>
      {%- if loop.index % 2 == 0 and not loop.last -%}
      <div style="page-break-after:always;"></div>
      {%- endif -%}
    {%- endfor -%}
  </div>

  <div class="pf-footer">
    End of Uploaded Documents &nbsp;|&nbsp; Application ID: {{ doc.name }}
    &nbsp;|&nbsp; Printed: {{ frappe.utils.formatdate(frappe.utils.nowdate(),'dd-MM-yyyy') }}
  </div>

</div>
{%- endif -%}
